import os
import ssl
import json
import asyncio
from typing import Optional, List, Dict, Any
import asyncpg
import httpx
from fastapi import FastAPI, HTTPException
from pydantic import BaseModel, Field
from pinecone import Pinecone

app = FastAPI()

class IngestRequest(BaseModel):
    id: str
    text: str
    metadata: Optional[Dict[str, Any]] = None

class QueryRequest(BaseModel):
    text: str
    top_k: int = Field(default=5, ge=1, le=100)
    alpha: Optional[float] = Field(default=None)

async def init_asyncpg_pool(dsn: str) -> asyncpg.Pool:
    sslctx = ssl.create_default_context()
    pool = await asyncpg.create_pool(dsn=dsn, ssl=sslctx, min_size=1, max_size=5, command_timeout=60)
    async with pool.acquire() as conn:
        await conn.execute("create table if not exists documents (id text primary key, text text not null, metadata jsonb, created_at timestamptz default now())")
    return pool

async def fetch_extensions(pool: asyncpg.Pool) -> List[Dict[str, Any]]:
    async with pool.acquire() as conn:
        rows = await conn.fetch("select extname, extversion from pg_extension")
        return [dict(r) for r in rows]

async def insert_document(pool: asyncpg.Pool, doc_id: str, text: str, metadata: Optional[Dict[str, Any]]) -> None:
    async with pool.acquire() as conn:
        await conn.execute("insert into documents (id, text, metadata) values ($1, $2, $3) on conflict (id) do update set text=excluded.text, metadata=excluded.metadata", doc_id, text, json.dumps(metadata) if metadata is not None else None)

async def get_document(pool: asyncpg.Pool, doc_id: str) -> Optional[Dict[str, Any]]:
    async with pool.acquire() as conn:
        row = await conn.fetchrow("select id, text, metadata, created_at from documents where id=$1", doc_id)
        return dict(row) if row else None

async def upstash_command(client: httpx.AsyncClient, base_url: str, token: str, command: List[Any]) -> Any:
    r = await client.post(base_url, headers={"Authorization": f"Bearer {token}"}, json={"command": command}, timeout=30)
    r.raise_for_status()
    return r.json()

async def upstash_set(client: httpx.AsyncClient, base_url: str, token: str, key: str, value: str) -> Any:
    return await upstash_command(client, base_url, token, ["SET", key, value])

async def upstash_get(client: httpx.AsyncClient, base_url: str, token: str, key: str) -> Any:
    return await upstash_command(client, base_url, token, ["GET", key])

async def jina_embed(client: httpx.AsyncClient, api_key: str, model: str, inputs: List[str]) -> List[float]:
    url = ""
    payload = {"model": model, "input": inputs}
    r = await client.post(url, headers={"Authorization": f"Bearer {api_key}", "Content-Type": "application/json"}, json=payload, timeout=60)
    r.raise_for_status()
    data = r.json()
    if "data" in data and data["data"] and "embedding" in data["data"][0]:
        return data["data"][0]["embedding"]
    raise HTTPException(status_code=502, detail="Invalid embedding response")

async def jina_rerank(client: httpx.AsyncClient, api_key: str, model: str, query: str, documents: List[str]) -> List[int]:
    url = ""
    payload = {"model": model, "query": query, "documents": documents}
    r = await client.post(url, headers={"Authorization": f"Bearer {api_key}", "Content-Type": "application/json"}, json=payload, timeout=60)
    r.raise_for_status()
    data = r.json()
    if "results" in data and isinstance(data["results"], list):
        scored = [(i, item.get("relevance_score", 0.0)) for i, item in enumerate(data["results"])]
        scored.sort(key=lambda x: x[1], reverse=True)
        return [i for i, _ in scored]
    return list(range(len(documents)))

async def pinecone_upsert(pc: Pinecone, index_name: str, vectors: List[Dict[str, Any]]) -> Any:
    def run():
        index = pc.Index(index_name)
        return index.upsert(vectors=vectors)
    return await asyncio.to_thread(run)

async def pinecone_query(pc: Pinecone, index_name: str, vector: List[float], top_k: int, alpha: Optional[float]) -> Dict[str, Any]:
    def run():
        index = pc.Index(index_name)
        kwargs = {"vector": vector, "top_k": top_k, "include_metadata": True}
        if alpha is not None:
            kwargs["alpha"] = alpha
        return index.query(**kwargs)
    return await asyncio.to_thread(run)

@app.on_event("startup")
async def startup():
    app.state.http = httpx.AsyncClient(timeout=60)
    tsdb_url = os.environ.get("TSDB_URL") or os.environ.get("TSDB") or os.environ.get("TSDB_DSN") or os.environ.get("TSDB_URL".upper())
    if not tsdb_url:
        tsdb_url = os.environ.get("TSDB_URL")
    if not tsdb_url:
