        raise HTTPException(status_code=503, detail="Database unavailable")
    return await fetch_extensions(app.state.pool)

@app.post("/ingest")
async def ingest(req: IngestRequest):
    if not app.state.pool:
        raise HTTPException(status_code=503, detail="Database unavailable")
    if not app.state.jina_key:
        raise HTTPException(status_code=503, detail="Jina unavailable")
    if not app.state.pinecone or not app.state.pinecone_index:
        raise HTTPException(status_code=503, detail="Pinecone unavailable")
    vec = await jina_embed(app.state.http, app.state.jina_key, app.state.jina_embed_model, [req.text])
    await insert_document(app.state.pool, req.id, req.text, req.metadata or {})
    meta = req.metadata or {}
    vectors = [{"id": req.id, "values": vec, "metadata": {"text_len": len(req.text), **meta}}]
    await pinecone_upsert(app.state.pinecone, app.state.pinecone_index, vectors)
    if app.state.upstash_url and app.state.upstash_token:
        await upstash_set(app.state.http, app.state.upstash_url, app.state.upstash_token, f"doc:{req.id}", json.dumps({"id": req.id, "text_len": len(req.text)}))
    return {"id": req.id, "upserted": True}

@app.post("/query")
async def query(req: QueryRequest):
    if not app.state.jina_key:
        raise HTTPException(status_code=503, detail="Jina unavailable")
    if not app.state.pinecone or not app.state.pinecone_index:
        raise HTTPException(status_code=503, detail="Pinecone unavailable")
    vec = await jina_embed(app.state.http, app.state.jina_key, app.state.jina_embed_model, [req.text])
    res = await pinecone_query(app.state.pinecone, app.state.pinecone_index, vec, req.top_k, req.alpha)
    matches = []
    if hasattr(res, "matches"):
        for m in res.matches:
            item = {"id": getattr(m, "id", None), "score": getattr(m, "score", None), "metadata": getattr(m, "metadata", None)}
            matches.append(item)
    elif isinstance(res, dict) and "matches" in res:
        for m in res["matches"]:
            matches.append({"id": m.get("id"), "score": m.get("score"), "metadata": m.get("metadata")})
    docs_text = []
    for m in matches:
        md = m.get("metadata") or {}
        t = None
        if isinstance(md, dict):
            t = md.get("text") or md.get("content") or None
        if t is None and app.state.pool:
            doc = await get_document(app.state.pool, m["id"])
            if doc:
                t = doc.get("text")
        docs_text.append(t if isinstance(t, str) else "")
    order = None
    if app.state.jina_key and len(docs_text) > 1:
        try:
            order = await jina_rerank(app.state.http, app.state.jina_key, app.state.jina_rerank_model, req.text, docs_text)
        except Exception:
            order = None
    if order is not None:
        reordered = [matches[i] for i in order if i < len(matches)]
        matches = reordered
    return {"matches": matches}

if __name__ == "__main__":
    import uvicorn
    port = int(os.environ.get("PORT", "8000"))
    uvicorn.run("app:app", host="0.0.0.0", port=port, reload=False)
