import os
import ssl
import json
import math
import asyncio
from typing import Optional, List, Dict, Any, Tuple
import asyncpg
import httpx
from fastapi import FastAPI, HTTPException
from pydantic import BaseModel, Field, validator

app = FastAPI()

class IngestRequest(BaseModel):
    id: str
    text: str
    metadata: Optional[Dict[str, Any]] = None
    @validator("id")
    def v_id(cls, v):
        if not v or not isinstance(v, str):
            raise ValueError("invalid id")
        return v
    @validator("text")
    def v_text(cls, v):
        if not v or not isinstance(v, str):
            raise ValueError("invalid text")
        return v

class QueryRequest(BaseModel):
    text: str
    top_k: int = Field(default=5, ge=1, le=100)
    alpha: Optional[float] = Field(default=None, ge=0.0, le=1.0)
    @validator("text")
    def q_text(cls, v):
        if not v or not isinstance(v, str):
            raise ValueError("invalid text")
        return v

async def init_asyncpg_pool(dsn: str) -> asyncpg.Pool:
    sslctx = ssl.create_default_context()
    pool = await asyncpg.create_pool(dsn=dsn, ssl=sslctx, min_size=1, max_size=5, command_timeout=60)
    async with pool.acquire() as conn:
        await conn.execute("create table if not exists documents (id text primary key, text text not null, metadata jsonb, created_at timestamptz default now())")
        await conn.execute("create table if not exists embeddings (id text primary key references documents(id) on delete cascade, dim integer not null, embedding double precision[] not null)")
        await conn.execute("create index if not exists embeddings_dim_idx on embeddings(dim)")
    return pool

async def fetch_extensions(pool: asyncpg.Pool) -> List[Dict[str, Any]]:
    async with pool.acquire() as conn:
        rows = await conn.fetch("select extname, extversion from pg_extension")
        return [dict(r) for r in rows]

async def insert_document(pool: asyncpg.Pool, doc_id: str, text: str, metadata: Optional[Dict[str, Any]]) -> None:
    async with pool.acquire() as conn:
        await conn.execute("insert into documents (id, text, metadata) values ($1, $2, $3) on conflict (id) do update set text=excluded.text, metadata=excluded.metadata", doc_id, text, metadata if metadata is not None else None)

async def upsert_embedding(pool: asyncpg.Pool, doc_id: str, embedding: List[float]) -> None:
    dim = len(embedding)
    async with pool.acquire() as conn:
        await conn.execute("insert into embeddings (id, dim, embedding) values ($1, $2, $3) on conflict (id) do update set dim=excluded.dim, embedding=excluded.embedding", doc_id, dim, embedding)

async def get_document(pool: asyncpg.Pool, doc_id: str) -> Optional[Dict[str, Any]]:
    async with pool.acquire() as conn:
        row = await conn.fetchrow("select id, text, metadata, created_at from documents where id=$1", doc_id)
        return dict(row) if row else None

async def get_all_embeddings(pool: asyncpg.Pool) -> List[Tuple[str, List[float]]]:
    async with pool.acquire() as conn:
        rows = await conn.fetch("select id, embedding from embeddings")
        out: List[Tuple[str, List[float]]] = []
        for r in rows:
            out.append((r["id"], list(r["embedding"])))
        return out

async def upstash_command(client: httpx.AsyncClient, base_url: str, token: str, command: List[Any]) -> Any:
