from fastapi import FastAPI, HTTPException
from pydantic import BaseModel, Field

app = FastAPI()

class IngestRequest(BaseModel):
    id: str = Field(..., min_length=1)
    text: str = Field(..., min_length=1)
    metadata: Optional[Dict[str, Any]] = None

class QueryRequest(BaseModel):
    text: str = Field(..., min_length=1)
    top_k: int = Field(default=5, ge=1, le=100)
    alpha: Optional[float] = Field(default=None, ge=0.0, le=1.0)

class ClaudeRequest(BaseModel):
    prompt: str = Field(..., min_length=1)
    max_tokens: int = Field(default=512, ge=1, le=8192)
    temperature: float = Field(default=0.2, ge=0.0, le=2.0)

async def init_asyncpg_pool(dsn: str) -> asyncpg.Pool:
    sslctx = ssl.create_default_context()
    pool = await asyncpg.create_pool(dsn=dsn, ssl=sslctx, min_size=1, max_size=5, command_timeout=60)
    async with pool.acquire() as conn:
        await conn.execute("create table if not exists documents (id text primary key, text text not null, metadata jsonb, created_at timestamptz default now())")
        await conn.execute("create table if not exists embeddings (id text primary key references documents(id) on delete cascade, dim integer not null, embedding double precision[] not null)")
        await conn.execute("create index if not exists embeddings_dim_idx on embeddings(dim)")
    return pool

async def fetch_extensions(pool: asyncpg.Pool) -> List[Dict[str, Any]]:
    async with pool.acquire() as conn:
        rows = await conn.fetch("select extname, extversion from pg_extension")
        return [dict(r) for r in rows]

async def insert_document(pool: asyncpg.Pool, doc_id: str, text: str, metadata: Optional[Dict[str, Any]]) -> None:
    async with pool.acquire() as conn:
        await conn.execute("insert into documents (id, text, metadata) values ($1, $2, $3) on conflict (id) do update set text=excluded.text, metadata=excluded.metadata", doc_id, text, metadata if metadata is not None else None)

async def upsert_embedding(pool: asyncpg.Pool, doc_id: str, embedding: List[float]) -> None:
    dim = len(embedding)
    async with pool.acquire() as conn:
        await conn.execute("insert into embeddings (id, dim, embedding) values ($1, $2, $3) on conflict (id) do update set dim=excluded.dim, embedding=excluded.embedding", doc_id, dim, embedding)

async def get_document(pool: asyncpg.Pool, doc_id: str) -> Optional[Dict[str, Any]]:
    async with pool.acquire() as conn:
        row = await conn.fetchrow("select id, text, metadata, created_at from documents where id=$1", doc_id)
        return dict(row) if row else None

async def get_all_embeddings(pool: asyncpg.Pool) -> List[Tuple[str, List[float]]]:
    async with pool.acquire() as conn:
        rows = await conn.fetch("select id, embedding from embeddings")
        out: List[Tuple[str, List[float]]] = []
        for r in rows:
            out.append((r["id"], list(r["embedding"])))
        return out

async def upstash_command(client: httpx.AsyncClient, base_url: str, token: str, command: List[Any]) -> Any:
    r = await client.post(base_url, headers={"Authorization": f"Bearer {token}"}, json={"command": command})
    r.raise_for_status()
    return r.json()

async def upstash_set(client: httpx.AsyncClient, base_url: str, token: str, key: str, value: str) -> Any:
    return await upstash_command(client, base_url, token, ["SET", key, value])

async def upstash_get(client: httpx.AsyncClient, base_url: str, token: str, key: str) -> Any:
    return await upstash_command(client, base_url, token, ["GET", key])

async def jina_embed(client: httpx.AsyncClient, api_key: str, model: str, inputs: List[str]) -> List[float]:
    url = ""
    payload = {"model": model, "input": inputs}
    r = await client.post(url, headers={"Authorization": f"Bearer {api_key}", "Content-Type": "application/json"}, json=payload)
    r.raise_for_status()
    data = r.json()
    if isinstance(data, dict) and "data" in data and data["data"] and "embedding" in data["data"][0]:
        emb = data["data"][0]["embedding"]
        if isinstance(emb, list) and all(isinstance(x, (int, float)) for x in emb):
            return [float(x) for x in emb]
    raise HTTPException(status_code=502, detail="invalid embedding response")

async def jina_rerank(client: httpx.AsyncClient, api_key: str, model: str, query: str, documents: List[str]) -> List[int]:
    url = ""
    payload = {"model": model, "query": query, "documents": documents}
    r = await client.post(url, headers={"Authorization": f"Bearer {api_key}", "Content-Type": "application/json"}, json=payload)
    r.raise_for_status()
    data = r.json()
    if isinstance(data, dict) and "results" in data and isinstance(data["results"], list):
        scored = [(i, float(item.get("relevance_score", 0.0))) for i, item in enumerate(data["results"])]
        scored.sort(key=lambda x: x[1], reverse=True)
        return [i for i, _ in scored]
    return list(range(len(documents)))

def cosine_similarity(a: List[float], b: List[float]) -> float:
    if not a or not b or len(a) != len(b):
        return -1.0
    dot = 0.0
    na = 0.0
    nb = 0.0
    for i in range(len(a)):
        av = float(a[i])
        bv = float(b[i])
        dot += av * bv
        na += av * av
        nb += bv * bv
    da = math.sqrt(na)
    db = math.sqrt(nb)
    if da == 0.0 or db == 0.0:
        return -1.0
    return dot / (da * db)

async def pinecone_upsert(pc_client: Any, index_name: str, vectors: List[Dict[str, Any]]) -> Any:
    def run():
        index = pc_client.Index(index_name)
        return index.upsert(vectors=vectors)
    return await asyncio.to_thread(run)

async def pinecone_query(pc_client: Any, index_name: str, vector: List[float], top_k: int, alpha: Optional[float]) -> Dict[str, Any]:
    def run():
        index = pc_client.Index(index_name)
        kwargs: Dict[str, Any] = {"vector": vector, "top_k": top_k, "include_metadata": True}
        if alpha is not None:
            kwargs["alpha"] = alpha
        return index.query(**kwargs)
    return await asyncio.to_thread(run)

async def bedrock_claude_complete(client: httpx.AsyncClient, bearer: str, region: str, model_id: str, prompt: str, max_tokens: int, temperature: float) -> str:
    url = f""
    payload = {
        "anthropic_version": "bedrock-2023-05-31",
        "messages": [
            {
                "role": "user",
                "content": [
                    {"type": "text", "text": prompt}
                ]
            }
        ],
        "max_tokens": max_tokens,
        "temperature": temperature
    }
    headers = {
        "Content-Type": "application/json",
        "Authorization": f"Bearer {bearer}"
    }
    r = await client.post(url, headers=headers, json=payload)
    r.raise_for_status()
    data = r.json()
    if isinstance(data, dict):
        if "content" in data and isinstance(data["content"], list) and data["content"]:
            part = data["content"][0]
            if isinstance(part, dict) and part.get("type") == "text" and isinstance(part.get("text"), str):
