    txt = await bedrock_claude_complete(app.state.http, app.state.aws_bedrock_bearer, app.state.aws_bedrock_region, app.state.aws_bedrock_model_id, req.prompt, req.max_tokens, req.temperature)
    return {"text": txt}

if __name__ == "__main__":
    import uvicorn
    port = int(os.environ.get("PORT", "8000"))
    uvicorn.run(app, host="0.0.0.0", port=port, reload=False)
