async function doClaude() {
  const input = $("#cl-prompt")
  const model = $("#model-select").value
  const maxTokens = parseInt($("#cl-max").value || "512", 10)
  const temp = parseFloat($("#cl-temp").value || "0.2")
  const text = input.value
  if(!text) return
  appendMsg("user", text)
  input.value = ""
  const botDiv = appendMsg("assistant", "")
  const ctrl = new AbortController()
  const body = JSON.stringify({prompt: text, max_tokens: maxTokens, temperature: temp, model: model})
  try {
    const resp = await fetch("/claude", {method:"POST", headers:{"Content-Type":"application/json"}, body, signal: ctrl.signal})
    if(!resp.ok){
      const t = await resp.text()
      botDiv.textContent = "Hiba: "+t
      return
    }
    const reader = resp.body.getReader()
    const decoder = new TextDecoder()
    let acc = ""
    while(true){
      const {done, value} = await reader.read()
      if(done) break
      const chunk = decoder.decode(value, {stream:true})
      acc += chunk
      botDiv.textContent = acc
      const log = $("#chat-log"); log.scrollTop = log.scrollHeight
    }
    const finalText = botDiv.textContent.trim()
    if(!finalText) botDiv.textContent = "(nincs válasz)"
  } catch(e){
    botDiv.textContent = "Hiba: "+String(e)
  }
}

